def shortest_with_all_letters(s1, s2):
  l, r = 0, 0
  missing = defaultdict(int)
  for c in s2:
    missing[c] += 1
  distinct_missing = len(missing)
  cur_min = math.inf

  while True:
    must_grow = distinct_missing > 0
    if must_grow:
      if r == len(s1):
        break
      if s1[r] in missing:
        missing[s1[r]] -= 1
        if missing[s1[r]] == 0:
          distinct_missing -= 1
      r += 1
    else:
      cur_min = min(cur_min, r - l)
      if s1[l] in missing:
        missing[s1[l]] += 1
        if missing[s1[l]] == 1:
          distinct_missing += 1
      l += 1
  return cur_min if cur_min != math.inf else -1

